WITH valid AS (SELECT id, product_name, category, stock_qty, launch_date, tags, CEIL(stock_qty) AS stock_qty_whole, FLOOR(price) AS price_whole FROM products WHERE launch_date >= TO_DATE('2023-06-01') AND LOWER(TRIM(product_name)) = 'office chair'), filtered AS (SELECT id, stock_qty, launch_date, tags, stock_qty_whole, ARRAY_JOIN(tags, ', ') AS tags_text FROM valid WHERE category = 'Grocery'), with_last AS (SELECT s.*, x.order_item_unit_price FROM filtered s LEFT JOIN LATERAL (SELECT c.unit_price AS order_item_unit_price FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) x ON TRUE), with_windows AS (SELECT *, ROW_NUMBER() OVER (ORDER BY launch_date DESC, id) AS event_seq, LAST_VALUE(stock_qty, TRUE) OVER (ORDER BY order_item_unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_stock_qty FROM with_last WHERE stock_qty_whole = 34), with_last_products AS (SELECT s.id, s.launch_date, s.tags, s.tags_text, s.event_seq, top1.inventory_last_restock, top1.quantity FROM with_windows s LEFT JOIN LATERAL (SELECT c.last_restock AS inventory_last_restock, c.quantity FROM inventory c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE), grouped AS (SELECT CASE WHEN quantity >= 253 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, DATE_TRUNC('MONTH', inventory_last_restock) AS activity_month, PERCENTILE_APPROX(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, MAX(event_seq) AS max_event_seq, APPROX_PERCENTILE(quantity, 0.95) AS quantity_p95, COUNT(DISTINCT id) AS distinct_ids, PERCENT_RANK() OVER (PARTITION BY CASE WHEN quantity >= 253 THEN 'HIGH' ELSE 'LOW' END ORDER BY APPROX_PERCENTILE(quantity, 0.95) DESC) AS quantity_p95_percent_rank FROM with_last_products GROUP BY quantity_tier, activity_month HAVING quantity_p95 < 1000000) SELECT quantity_tier, activity_month, event_seq_quartiles, max_event_seq, quantity_p95, distinct_ids FROM grouped;
